const checklist=['Реквизиты участника проверены','Техническое предложение подготовлено','Цена и условия согласованы','Приложения сверены с документацией'];
function hasBlanks(d){return /\[[^\]]+\]/.test((d.body||'')+' '+(d.notes||''));}
function draftReadiness(d){if(hasBlanks(d))return 'Есть незаполненные места';if(d.type==='Заявка'&&(d.checks||[]).length<4)return 'Комплект не проверен';return 'Черновик · не отправлен';}
function reviewPanel(i){const d=drafts[i];return `<div class="review-banner ${hasBlanks(d)?'needs-work':''}"><strong>${draftReadiness(d)}</strong><p>${hasBlanks(d)?'В тексте остались подсказки в квадратных скобках. Замените их перед использованием.':'Проверьте сведения перед использованием документа.'}</p></div>${d.type==='Заявка'?`<div class="checklist"><h3>Готовность комплекта <span id="check-progress">${(d.checks||[]).length}/4</span></h3><p>Отмечается вручную. Приложения не загружены и не проверены системой.</p>${checklist.map((label,k)=>`<label><input type="checkbox" data-check="${k}" data-draft="${i}" ${(d.checks||[]).includes(k)?'checked':''}><span>${label}</span></label>`).join('')}</div>`:''}`;}
function documentHtml(d){const base=Math.round(Number(d.qty)*Number(d.price)*100)/100,tax=Math.round(base*Number(d.vat)/100*100)/100;return `<!doctype html><html lang="ru"><meta charset="utf-8"><title>${esc(d.type)} № ${esc(d.number)}</title><style>body{font:15px/1.65 Arial,sans-serif;max-width:850px;margin:45px auto;padding:0 30px;color:#172b47}h1{font-size:28px;border-bottom:3px solid #3256de;padding-bottom:18px}small{color:#77849a}.draft-label{font-size:12px;letter-spacing:2px;color:#b37931}.parties{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin:25px 0}.parties strong{display:block}table{border-collapse:collapse;width:100%;margin:25px 0}td,th{padding:12px;border:1px solid #dce2ec;text-align:left;overflow-wrap:anywhere}th{background:#f2f5fa;font-size:12px}.totals{text-align:right}.totals strong{font-size:22px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}button{background:#3154e4;color:white;border:0;border-radius:7px;padding:12px 20px;cursor:pointer}.warning{background:#fff4df;padding:12px}@media print{body{margin:0;max-width:none;padding:0}button{display:none}@page{size:A4;margin:18mm}}</style><body><button onclick="window.print()">Печать / сохранить PDF</button><p class="draft-label">ЧЕРНОВИК · НЕ ОТПРАВЛЕН</p><h1>${esc(d.type)} № ${esc(d.number)}</h1><small>Дата: ${esc(d.date)}</small><div class="parties"><div><small>Поставщик / отправитель</small><strong>${esc(d.seller)}</strong></div><div><small>Плательщик / получатель</small><strong>${esc(d.buyer)}</strong></div></div>${hasBlanks(d)?'<p class="warning">В документе остались незаполненные места.</p>':''}${d.type==='Счёт'?`<table><thead><tr><th>Наименование</th><th>Кол-во</th><th>Цена без НДС, ₽</th><th>Сумма без НДС, ₽</th></tr></thead><tbody><tr><td>${esc(d.item)}</td><td>${esc(d.qty)}</td><td>${cash(Number(d.price))}</td><td>${cash(base)}</td></tr></tbody></table><div class="totals">Без НДС: ${cash(base)} ₽<br>НДС (${esc(d.vat)}%): ${cash(tax)} ₽<br><strong>Итого: ${cash(base+tax)} ₽</strong></div><h3>Реквизиты</h3><pre>${esc(d.details)}</pre>`:`<pre>${esc(d.body)}</pre>`}${d.notes?`<h3>Примечания и условия</h3><pre>${esc(d.notes)}</pre>`:''}<p><small>Основание: ${esc(d.source)}</small></p><p><small>Документ подготовлен по шаблону. Сведения и приложения требуют проверки.</small></p></body></html>`;}
let mailQuery='',mailScope='all';const queueTools=document.createElement('div');queueTools.className='queue-tools';queueTools.innerHTML='<label class="search"><span>⌕</span><input id="mail-search" aria-label="Поиск по письмам" placeholder="Поиск по письмам"></label><div class="queue-tabs"><button data-scope="all" class="selected">Все</button><button data-scope="open">В работе</button><button data-scope="done">Обработано</button></div>';document.querySelector('#mail-list').before(queueTools);
const originalRenderMail=renderMail;renderMail=function(){originalRenderMail();let visible=0;document.querySelectorAll('[data-mail]').forEach(el=>{const m=mails[Number(el.dataset.mail)],match=(!mailQuery||`${m.subject} ${m.from} ${m.body}`.toLowerCase().includes(mailQuery))&&(mailScope==='all'||(mailScope==='done'?m.done:!m.done));el.hidden=!match;if(match)visible++;if(m.done)el.querySelector('.status').textContent='✓ Обработано';});document.querySelector('.inbox .tag').textContent=`${mails.filter(m=>!m.done).length} в работе`;if(!visible)document.querySelector('#mail-list').insertAdjacentHTML('beforeend','<div class="queue-empty">Нет писем по выбранному фильтру</div>');document.querySelector('.mail-actions').insertAdjacentHTML('beforeend',`<button class="button done-button" id="mark-done">${mails[selectedMail].done?'Вернуть в работу':'✓ Обработано'}</button>`);};
document.querySelector('#mail-search').addEventListener('input',e=>{mailQuery=e.target.value.trim().toLowerCase();renderMail();});
document.addEventListener('change',e=>{if(e.target.dataset.check!==undefined){const d=drafts[Number(e.target.dataset.draft)],k=Number(e.target.dataset.check);d.checks=e.target.checked?[...new Set([...(d.checks||[]),k])]:(d.checks||[]).filter(v=>v!==k);document.querySelector('#check-progress').textContent=`${d.checks.length}/4`;renderDrafts();}});
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.scope){mailScope=t.dataset.scope;document.querySelectorAll('[data-scope]').forEach(b=>b.classList.toggle('selected',b===t));renderMail();}if(t.id==='mark-done'){mails[selectedMail].done=!mails[selectedMail].done;renderMail();}if(t.dataset.revise!==undefined){const i=Number(t.dataset.revise);if(compose.open)compose.close();openCompose(drafts[i].type,i);}if(t.dataset.copyDraft!==undefined){const d=drafts[Number(t.dataset.copyDraft)];drafts.push({...d,number:d.number+'-копия',checks:[]});renderDrafts();compose.close();}if(t.dataset.html!==undefined){const d=drafts[Number(t.dataset.html)],url=URL.createObjectURL(new Blob([documentHtml(d)],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`${d.type}-${d.number.replace(/[^\p{L}\p{N}-]/gu,'_')}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});renderMail();
